import org.koin.dsl.koinConfiguration
import org.koin.dsl.module

/**
 * Sets the content for the UI test wrapped inside Koin.
 *
 * Every composable under test needs a [Settings] binding, so one is always registered. Pass
 * [settings] to seed stored preferences (defaults to an empty [MapSettings]); supply any further
 * Koin bindings a specific test needs via [extraModules].
 *
 * @param settings the [Settings] instance exposed to the composables under test
 * @param extraModules extra Koin modules to register on top of the [Settings] binding
 * @param content Composable content for testing
 * @param onContent Non-composable code for testing, maybe dependent upon composable code
 */
@OptIn(ExperimentalTestApi::class)
inline fun ComposeUiTest.withKoin(
    settings: Settings = MapSettings(),
    extraModules: List<Module> = emptyList(),
    noinline content: @Composable () -> Unit = {},
    onContent: () -> Unit = {}
) {
    try {
        setContent {
            KoinApplication(
                configuration = koinConfiguration {
                    modules(listOf(module { single { settings } }) + extraModules)
                },
                logLevel = Level.DEBUG,
                content = content
            )
        }
        onContent()
    } finally {
        stopKoin()
    }
}

